{
  "title": "GetProductsRequest",
  "properties": {
    "buying_mode": {"type": "string"},
    "refine": {
      "type": "array",
      "description": "Array of change requests for iterating on products and proposals from a previous response. The seller responds to each entry via refinement_applied, matched by position.",
      "items": {
        "discriminator": {"propertyName": "scope"},
        "oneOf": [
          {"properties": {"scope": {"const": "request"}, "ask": {"type": "string", "minLength": 1}}, "required": ["scope", "ask"]},
          {"properties": {"scope": {"const": "product"}, "product_id": {"type": "string"}, "action": {"type": "string", "enum": ["include", "omit", "more_like_this"]}}, "required": ["scope", "product_id"]},
          {"properties": {"scope": {"const": "proposal"}, "proposal_id": {"type": "string"}, "action": {"type": "string", "enum": ["include", "omit", "finalize"]}}, "required": ["scope", "proposal_id"]}
        ]
      }
    }
  },
  "required": ["buying_mode"]
}
